import json
def transform(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    # find 2x2 blocks
    blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==2 and g[r][c+1]==2 and g[r+1][c]==2 and g[r+1][c+1]==2:
                blocks.append((r,c))
    for (r,c) in blocks:
        slots={  # diag-adjacent cell -> its block corner (TL,TR,BR,BL)
            (r-1,c-1):(r,c,'UL'),(r-1,c+2):(r,c+1,'UR'),
            (r+2,c+2):(r+1,c+1,'DR'),(r+2,c-1):(r+1,c,'DL')}
        colors={}
        for (sr,sc),(cr,cc,d) in slots.items():
            if 0<=sr<h and 0<=sc<w and g[sr][sc] not in (0,2):
                colors[d]=g[sr][sc]
                out[sr][sc]=0
        # clockwise: UL->UR->DR->DL->UL ; ray dir per new corner
        move={'UL':'UR','UR':'DR','DR':'DL','DL':'UL'}
        raydir={'UL':(-1,-1),'UR':(-1,1),'DR':(1,1),'DL':(1,-1)}
        cornercell={'UL':(r,c),'UR':(r,c+1),'DR':(r+1,c+1),'DL':(r+1,c)}
        for d,col in colors.items():
            nd=move[d]
            cr,cc=cornercell[nd]
            # slot adjacent to new corner
            sr,sc=cr+raydir[nd][0],cc+raydir[nd][1]
            rr,rc=cr,cc
            # step outward from slot to edge
            while 0<=sr<h and 0<=sc<w:
                out[sr][sc]=col
                sr+=raydir[nd][0]; sc+=raydir[nd][1]
    return out
